/// spec class `ScheduleTableEntry` (abstract)
/// Table entry in a LinScheduleTable. Specifies what will be done in the frame slot.
#[derive(Debug, Default)]
pub struct ScheduleTableEntry {
    base: ARObject,
    delay: Option<String>,
    introduction: Option<DocumentationBlockId>,
    position_in_table: Option<String>,
}

impl ScheduleTableEntry {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn base(&self) -> &ARObject {
        &self.base
    }

    pub fn base_mut(&mut self) -> &mut ARObject {
        &mut self.base
    }

    pub fn get_delay(&self) -> Option<&str> {
        self.delay.as_deref()
    }

    pub fn set_delay(&mut self, value: impl Into<String>) -> &mut Self {
        self.delay = Some(value.into());
        self
    }

    pub fn get_introduction(&self) -> Option<DocumentationBlockId> {
        self.introduction
    }

    pub fn set_introduction(&mut self, value: DocumentationBlockId) -> &mut Self {
        self.introduction = Some(value);
        self
    }

    pub fn get_position_in_table(&self) -> Option<&str> {
        self.position_in_table.as_deref()
    }

    pub fn set_position_in_table(&mut self, value: impl Into<String>) -> &mut Self {
        self.position_in_table = Some(value.into());
        self
    }

    pub fn get_checksum(&self) -> Option<&str> {
        self.base().get_checksum()
    }

    pub fn set_checksum(&mut self, value: impl Into<String>) -> &mut Self {
        self.base_mut().set_checksum(value);
        self
    }

    pub fn get_timestamp(&self) -> Option<&str> {
        self.base().get_timestamp()
    }

    pub fn set_timestamp(&mut self, value: impl Into<String>) -> &mut Self {
        self.base_mut().set_timestamp(value);
        self
    }
}

