impl Document {
    pub(crate) fn compare_application_entry(
        &self,
        other: &Document,
        a: &ApplicationEntry,
        b: &ApplicationEntry,
        path: &str,
    ) -> Result<(), String> {
        self.compare_schedule_table_entry(other, a.base(), b.base(), path)?;
        if a.get_frame_triggering_ref() != b.get_frame_triggering_ref() {
            return Err(format!("{path}: FRAME_TRIGGERING_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_assign_frame_id(
        &self,
        other: &Document,
        a: &AssignFrameId,
        b: &AssignFrameId,
        path: &str,
    ) -> Result<(), String> {
        self.compare_lin_configuration_entry(other, a.base(), b.base(), path)?;
        if a.get_assigned_frame_triggering_ref() != b.get_assigned_frame_triggering_ref() {
            return Err(format!("{path}: ASSIGNED_FRAME_TRIGGERING_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_assign_frame_id_range(
        &self,
        other: &Document,
        a: &AssignFrameIdRange,
        b: &AssignFrameIdRange,
        path: &str,
    ) -> Result<(), String> {
        self.compare_lin_configuration_entry(other, a.base(), b.base(), path)?;
        let list_a = a.get_frame_pids();
        let list_b = b.get_frame_pids();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: FRAME_PIDS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .frame_pids
                .get(*x)
                .ok_or_else(|| format!("{path}.FRAME_PIDS[{index}]: id not found in own arena"))?;
            let y = other.frame_pids.get(*y).ok_or_else(|| {
                format!("{path}.FRAME_PIDS[{index}]: id not found in other arena")
            })?;
            self.compare_frame_pid(other, x, y, &format!("{path}.FRAME_PIDS[{index}]"))?;
        }
        if a.get_start_index() != b.get_start_index() {
            return Err(format!("{path}: START_INDEX mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_assign_nad(
        &self,
        other: &Document,
        a: &AssignNad,
        b: &AssignNad,
        path: &str,
    ) -> Result<(), String> {
        self.compare_lin_configuration_entry(other, a.base(), b.base(), path)?;
        if a.get_new_nad() != b.get_new_nad() {
            return Err(format!("{path}: NEW_NAD mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_conditional_change_nad(
        &self,
        other: &Document,
        a: &ConditionalChangeNad,
        b: &ConditionalChangeNad,
        path: &str,
    ) -> Result<(), String> {
        self.compare_lin_configuration_entry(other, a.base(), b.base(), path)?;
        if a.get_byte() != b.get_byte() {
            return Err(format!("{path}: BYTE mismatch"));
        }
        if a.get_id() != b.get_id() {
            return Err(format!("{path}: ID mismatch"));
        }
        if a.get_invert() != b.get_invert() {
            return Err(format!("{path}: INVERT mismatch"));
        }
        if a.get_mask() != b.get_mask() {
            return Err(format!("{path}: MASK mismatch"));
        }
        if a.get_new_nad() != b.get_new_nad() {
            return Err(format!("{path}: NEW_NAD mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_data_dump_entry(
        &self,
        other: &Document,
        a: &DataDumpEntry,
        b: &DataDumpEntry,
        path: &str,
    ) -> Result<(), String> {
        self.compare_lin_configuration_entry(other, a.base(), b.base(), path)?;
        let list_a = a.get_byte_values();
        let list_b = b.get_byte_values();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: BYTE_VALUES length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.BYTE_VALUES[{index}] mismatch"));
            }
        }
        Ok(())
    }

    pub(crate) fn compare_frame_pid(
        &self,
        _other: &Document,
        a: &FramePid,
        b: &FramePid,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_index() != b.get_index() {
            return Err(format!("{path}: INDEX mismatch"));
        }
        if a.get_pid() != b.get_pid() {
            return Err(format!("{path}: PID mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_free_format(
        &self,
        other: &Document,
        a: &FreeFormat,
        b: &FreeFormat,
        path: &str,
    ) -> Result<(), String> {
        self.compare_free_format_entry(other, a.base(), b.base(), path)?;
        let list_a = a.get_byte_values();
        let list_b = b.get_byte_values();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: BYTE_VALUES length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.BYTE_VALUES[{index}] mismatch"));
            }
        }
        Ok(())
    }

    pub(crate) fn compare_free_format_entry(
        &self,
        other: &Document,
        a: &FreeFormatEntry,
        b: &FreeFormatEntry,
        path: &str,
    ) -> Result<(), String> {
        self.compare_schedule_table_entry(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_lin_configuration_entry(
        &self,
        other: &Document,
        a: &LinConfigurationEntry,
        b: &LinConfigurationEntry,
        path: &str,
    ) -> Result<(), String> {
        self.compare_schedule_table_entry(other, a.base(), b.base(), path)?;
        if a.get_assigned_controller_ref() != b.get_assigned_controller_ref() {
            return Err(format!("{path}: ASSIGNED_CONTROLLER_REF mismatch"));
        }
        if a.get_assigned_lin_slave_config_ref() != b.get_assigned_lin_slave_config_ref() {
            return Err(format!("{path}: ASSIGNED_LIN_SLAVE_CONFIG_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_lin_error_response(
        &self,
        _other: &Document,
        a: &LinErrorResponse,
        b: &LinErrorResponse,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_response_error_ref() != b.get_response_error_ref() {
            return Err(format!("{path}: RESPONSE_ERROR_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_lin_event_triggered_frame(
        &self,
        other: &Document,
        a: &LinEventTriggeredFrame,
        b: &LinEventTriggeredFrame,
        path: &str,
    ) -> Result<(), String> {
        self.compare_lin_frame(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_lin_frame(
        &self,
        other: &Document,
        a: &LinFrame,
        b: &LinFrame,
        path: &str,
    ) -> Result<(), String> {
        self.compare_frame(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_lin_frame_triggering(
        &self,
        other: &Document,
        a: &LinFrameTriggering,
        b: &LinFrameTriggering,
        path: &str,
    ) -> Result<(), String> {
        self.compare_frame_triggering(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_lin_schedule_table(
        &self,
        other: &Document,
        a: &LinScheduleTable,
        b: &LinScheduleTable,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        if a.get_resume_position() != b.get_resume_position() {
            return Err(format!("{path}: RESUME_POSITION mismatch"));
        }
        if a.get_run_mode() != b.get_run_mode() {
            return Err(format!("{path}: RUN_MODE mismatch"));
        }
        let list_a = a.get_table_entries();
        let list_b = b.get_table_entries();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: TABLE_ENTRIES length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.TABLE_ENTRIES[{index}] mismatch"));
            }
        }
        Ok(())
    }

    pub(crate) fn compare_lin_sporadic_frame(
        &self,
        other: &Document,
        a: &LinSporadicFrame,
        b: &LinSporadicFrame,
        path: &str,
    ) -> Result<(), String> {
        self.compare_lin_frame(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_lin_unconditional_frame(
        &self,
        other: &Document,
        a: &LinUnconditionalFrame,
        b: &LinUnconditionalFrame,
        path: &str,
    ) -> Result<(), String> {
        self.compare_lin_frame(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_save_configuration_entry(
        &self,
        other: &Document,
        a: &SaveConfigurationEntry,
        b: &SaveConfigurationEntry,
        path: &str,
    ) -> Result<(), String> {
        self.compare_lin_configuration_entry(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_schedule_table_entry(
        &self,
        _other: &Document,
        a: &ScheduleTableEntry,
        b: &ScheduleTableEntry,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_delay() != b.get_delay() {
            return Err(format!("{path}: DELAY mismatch"));
        }
        if a.get_introduction() != b.get_introduction() {
            return Err(format!("{path}: INTRODUCTION mismatch"));
        }
        if a.get_position_in_table() != b.get_position_in_table() {
            return Err(format!("{path}: POSITION_IN_TABLE mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_unassign_frame_id(
        &self,
        other: &Document,
        a: &UnassignFrameId,
        b: &UnassignFrameId,
        path: &str,
    ) -> Result<(), String> {
        self.compare_lin_configuration_entry(other, a.base(), b.base(), path)?;
        if a.get_unassigned_frame_triggering_ref() != b.get_unassigned_frame_triggering_ref() {
            return Err(format!("{path}: UNASSIGNED_FRAME_TRIGGERING_REF mismatch"));
        }
        Ok(())
    }
}
